1139		for _, svc := range []string{"s1", "s2"} {
1140			registerService(t, r, svc, 0, []Instance{{ID: "a", Address: "h1:1"}, {ID: "b", Address: "h2:2"}})
1141			markHealth(t, r, svc, "a", 1, 1, true, "")
1142			markHealth(t, r, svc, "b", 1, 1, true, "")
1143		}
1144		// The same key binds independently per service.
1145		if out := selectedWithSession(t, r, "s1", 1, "k"); out.InstanceID != "a" {
1146			t.Fatalf("s1 bind: %+v", out)
1147		}
