1163	func TestRegistrySelectSessionFailuresKeepBindingAndCursor(t *testing.T) {
1164		r := NewRegistry()
1165		registerService(t, r, "svc", 0, []Instance{{ID: "a", Address: "h1:1"}, {ID: "b", Address: "h2:2"}})
1166		markHealth(t, r, "svc", "a", 1, 1, true, "")
1167		markHealth(t, r, "svc", "b", 1, 1, true, "")
1168	
1169		// A conflicting session select creates no binding and moves no cursor.
1170		sel, err := r.ValidateSelectionWithSession("svc", 9, strPtr("s"))
1171		if err != nil {
