1173		}
1174		if out := r.Select(sel); out.OK || out.Kind != OutcomeConflict {
1175			t.Fatalf("conflict select: %+v", out)
1176		}
1177		// The first successful select (plain) still takes the smallest id.
1178		if out := selected(t, r, "svc", 1); out.InstanceID != "a" {
1179			t.Fatalf("plain select after conflict: %+v", out)
1180		}
1181		// The key was never bound: its first success rotates after a to b.
1182		if out := selectedWithSession(t, r, "svc", 1, "s"); out.InstanceID != "b" {
1183			t.Fatalf("first session success should rotate to b: %+v", out)
1184		}
