1197		markHealth(t, r, "svc", "b", 1, 3, true, "")
1198		if out := selectedWithSession(t, r, "svc", 1, "s"); out.InstanceID != "b" || out.Sequence != 3 {
1199			t.Fatalf("binding should survive no_healthy: %+v", out)
