3	import "testing"
4	
5	// This file is the domain-level regression guard for health-record isolation
6	// between services that reuse the same instance identifier. An instance id is
7	// only meaningful inside its own service: two services may both register "i1"
8	// — even with the very same address — and each must keep its own health state,
9	// sequence and reason. These tests drive the public Validate/Apply/Select and
10	// Snapshot APIs to lock that isolation:
11	//
12	//   - interleaved observations compare only against the owning service's
13	//     accepted record: one service's i1 at sequence 20 never makes the other
14	//     service's i1 sequence 1 stale, and no reason leaks across;
15	//   - stale and same-sequence conflicting reports fail against the targeted
16	//     service's own current sequence and overwrite neither service's record,
17	//     while a later valid observation in the same service still lands;
18	//   - target selection reflects each service's own accepted health: the
19	//     all-unhealthy service answers no_healthy while the other still selects
20	//     its own healthy instance with its own address and latest sequence, and a
21	//     recovery in one service never changes the other's state;
22	//   - health observations never bump either service's registration revision.
23	
24	// reportHealth validates and applies one health observation, returning the raw
25	// outcome so both accepted and rejected reports can be asserted.
26	func reportHealth(t *testing.T, r *Registry, service, id string, revision int64, sequence int64, healthy bool, reason string) HealthOutcome {
27		t.Helper()
28		upd, err := r.ValidateHealth(service, id, revision, sequence, healthy, reason)
29		if err != nil {
30			t.Fatalf("validate health %s/%s: %v", service, id, err)
31		}
32		return r.ApplyHealth(upd)
33	}
34	
35	// trySelect validates and runs one plain selection, returning the raw outcome
36	// so both successful and failed selections can be asserted.
37	func trySelect(t *testing.T, r *Registry, service string, revision int64) SelectOutcome {
38		t.Helper()
39		sel, err := r.ValidateSelection(service, revision)
40		if err != nil {
41			t.Fatalf("validate select %s: %v", service, err)
42		}
43		return r.Select(sel)
44	}
45	
46	// assertHealth locks one accepted observation's result: success, the change
47	// flag, the owning service's revision and the instance's new sequence.
48	func assertHealth(t *testing.T, out HealthOutcome, revision int, sequence int64) {
49		t.Helper()
50		if !out.OK || !out.Changed || out.Revision != revision || out.Sequence != sequence {
51			t.Fatalf("health outcome = %+v, want ok changed revision %d sequence %d", out, revision, sequence)
52		}
53	}
54	
55	// TestRegistryHealthSameIDAndAddressIsolatedAcrossServices interleaves
56	// observations for two services that both register an instance "i1" at the
57	// SAME address. Every observation must be judged against the owning service's
58	// own accepted record only.
59	func TestRegistryHealthSameIDAndAddressIsolatedAcrossServices(t *testing.T) {
60		r := NewRegistry()
61		for _, svc := range []string{"svc-a", "svc-b"} {
62			registerService(t, r, svc, 0, []Instance{{ID: "i1", Address: "h1:8080"}})
63		}
64	
65		// svc-a's i1 accepts an unhealthy observation at sequence 20; the trimmed
66		// reason is stored on svc-a's record only.
67		assertHealth(t, reportHealth(t, r, "svc-a", "i1", 1, 20, false, " 心跳超时 "), 1, 20)
68	
69		// svc-b's i1 still accepts sequence 1: svc-a's higher sequence must not
70		// make it stale, and svc-a's reason must not leak into svc-b's record.
71		assertHealth(t, reportHealth(t, r, "svc-b", "i1", 1, 1, true, ""), 1, 1)
72		if inst := instanceHealth(t, r, "svc-b", "i1"); inst.Health != HealthHealthy || inst.Sequence != 1 || inst.Reason != "" {
73			t.Fatalf("svc-b/i1 should be healthy at its own sequence 1 with no reason, got %+v", inst)
74		}
75		if inst := instanceHealth(t, r, "svc-a", "i1"); inst.Health != HealthUnhealthy || inst.Sequence != 20 || inst.Reason != "心跳超时" {
76			t.Fatalf("svc-a/i1 should be unhealthy at sequence 20 with its trimmed reason, got %+v", inst)
77		}
78	
79		// A stale report to svc-a is judged against svc-a's own current sequence
80		// 20 — not svc-b's 1 — and reports that sequence.
81		if out := reportHealth(t, r, "svc-a", "i1", 1, 5, true, ""); out.OK || out.Kind != OutcomeStale ||
82			out.Sequence != 20 || out.Revision != 1 {
83			t.Fatalf("stale report should state svc-a's own current sequence 20, got %+v", out)
84		}
85		// The same sequence 20 with different health content conflicts against
86		// svc-a's record; svc-b's identical-id record is not consulted.
87		if out := reportHealth(t, r, "svc-a", "i1", 1, 20, false, "别的理由"); out.OK || out.Kind != OutcomeConflict ||
88			out.Sequence != 20 || out.Revision != 1 {
89			t.Fatalf("conflicting report should state svc-a's own current sequence 20, got %+v", out)
90		}
91		// Neither rejection overwrote svc-a's record nor touched svc-b's.
92		if inst := instanceHealth(t, r, "svc-a", "i1"); inst.Health != HealthUnhealthy || inst.Sequence != 20 || inst.Reason != "心跳超时" {
93			t.Fatalf("rejected reports must not overwrite svc-a/i1, got %+v", inst)
94		}
95		if inst := instanceHealth(t, r, "svc-b", "i1"); inst.Health != HealthHealthy || inst.Sequence != 1 || inst.Reason != "" {
96			t.Fatalf("svc-a's rejected reports must not touch svc-b/i1, got %+v", inst)
97		}
