100		// effect at its OWN next sequence 2 — svc-a's accepted 20 is irrelevant.
101		assertHealth(t, reportHealth(t, r, "svc-b", "i1", 1, 2, false, "磁盘故障"), 1, 2)
102		// And svc-a recovers at its own next sequence 21 while svc-b's record
103		// stays exactly where svc-b left it.
104		assertHealth(t, reportHealth(t, r, "svc-a", "i1", 1, 21, true, ""), 1, 21)
105	
106		// The snapshot shows two fully independent records under the same id and
107		// address; neither health report bumped a registration revision.
108		views := r.Snapshot()
109		if len(views) != 2 {
