113			t.Fatalf("health reports must not bump revisions: %+v", views)
114		}
115		wantA := InstanceView{ID: "i1", Address: "h1:8080", Health: HealthHealthy, Sequence: 21}
116		if len(views[0].Instances) != 1 || views[0].Instances[0] != wantA {
117			t.Fatalf("svc-a/i1: got %+v want %+v", views[0].Instances, wantA)
118		}
119		wantB := InstanceView{ID: "i1", Address: "h1:8080", Health: HealthUnhealthy, Sequence: 2, Reason: "磁盘故障"}
120		if len(views[1].Instances) != 1 || views[1].Instances[0] != wantB {
121			t.Fatalf("svc-b/i1: got %+v want %+v", views[1].Instances, wantB)
122		}
