125	// TestRegistrySelectSameIDReflectsOwnServiceHealth locks selection isolation:
126	// each service's select sees only its own accepted health records, even when
127	// both services name their instance "i1" at the same address.
128	func TestRegistrySelectSameIDReflectsOwnServiceHealth(t *testing.T) {
