147		markHealth(t, r, "svc-a", "i1", 1, 8, true, "")
148		assertPick(t, trySelect(t, r, "svc-a", 1), "i1", "h1:8080", 8)
149		// …without changing svc-b's record or its next selection.
150		assertPick(t, trySelect(t, r, "svc-b", 1), "i1", "h1:8080", 1)
151		if inst := instanceHealth(t, r, "svc-b", "i1"); inst.Health != HealthHealthy || inst.Sequence != 1 || inst.Reason != "" {
152			t.Fatalf("svc-a's recovery must not affect svc-b/i1, got %+v", inst)
